        "code": "// LeetCode 42: Trapping Rain Water\n// Time Complexity: O(N) where N is the number of elements in the array\n// Space Complexity: O(1) auxiliary space\n\npublic class TrappingRainWater {\n\n    /**\n     * Calculates the amount of rain water that can be trapped.\n     * @param height Array of bar heights\n     * @return Total trapped rain water\n     */\n    public static int trap(int[] height) {\n        if (height == null || height.length < 3) {\n            return 0;\n        }\n\n        int left = 0;\n        int right = height.length - 1;\n        int leftMax = 0;\n        int rightMax = 0;\n        int totalWater = 0;\n\n        while (left < right) {\n            if (height[left] < height[right]) {\n                if (height[left] >= leftMax) {\n                    leftMax = height[left];\n                } else {\n                    totalWater += (leftMax - height[left]);\n                }\n                left++;\n            } else {\n                if (height[right] >= rightMax) {\n                    rightMax = height[right];\n                } else {\n                    totalWater += (rightMax - height[right]);\n                }\n                right--;\n            }\n        }\n\n        return totalWater;\n    }\n\n    public static void main(String[] args) {\n        int[] height = {0, 1, 0, 2, 1, 0, 1, 3, 2, 1, 2, 1};\n        System.out.print(\"Elevation map: \");\n        printArray(height);\n        \n        int trappedWater = trap(height);\n        System.out.println(\"Total trapped rain water: \" + trappedWater); // Expected: 6\n    }\n    \n    private static void printArray(int[] arr) {\n        System.out.print(\"[\");\n        for (int i = 0; i < arr.length; i++) {\n            System.out.print(arr[i]);\n            if (i < arr.length - 1) {\n                System.out.print(\", \");\n            }\n        }\n        System.out.println(\"]\");\n    }\n}\n"
