        "title": "Find Cycle Start in Linked List",
        "sourceUrl": "https://leetcode.com/problems/linked-list-cycle-ii/",
        "fileName": "LinkedListCycleStart.java",
        "filePath": "FastAndSlowPointers/LinkedListCycleStart.java",
        "timeComplexity": "O(N)",
        "spaceComplexity": "O(1)",
        "approach": "Floyd's cycle detection + head reset and linear meeting",
        "code": "// LeetCode 142: Linked List Cycle II (Find Cycle Start)\n// Time Complexity: O(N) where N is the number of nodes in the linked list\n// Space Complexity: O(1) auxiliary space\n\npublic class LinkedListCycleStart {\n\n    /**\n     * Finds the node where the cycle begins in the linked list.\n     * @param head The head of the linked list\n     * @return The node where the cycle starts, or null if no cycle exists\n     */\n    public static ListNode detectCycle(ListNode head) {\n        if (head == null || head.next == null) {\n            return null;\n        }\n\n        ListNode slow = head;\n        ListNode fast = head;\n        boolean hasCycle = false;\n\n        // Step 1: Detect if a cycle exists\n        while (fast != null && fast.next != null) {\n            slow = slow.next;\n            fast = fast.next.next;\n\n            if (slow == fast) {\n                hasCycle = true;\n                break;\n            }\n        }\n\n        if (!hasCycle) {\n            return null; // No cycle\n        }\n\n        // Step 2: Find the start of the cycle\n        slow = head; // Reset slow to the head\n        while (slow != fast) {\n            slow = slow.next; // Move slow 1 step\n            fast = fast.next; // Move fast 1 step\n        }\n\n        return slow; // The start of the cycle\n    }\n\n    public static void main(String[] args) {\n        // Create a list with a cycle: [3, 2, 0, -4], cycle tail points to 2 (index 1)\n        int[] arr = {3, 2, 0, -4};\n        ListNode head = ListNode.createList(arr);\n        \n        ListNode tail = head;\n        while (tail.next != null) {\n            tail = tail.next;\n        }\n        ListNode cycleStartNode = head.next; // The node with value 2\n        tail.next = cycleStartNode;          // Create the cycle\n\n        System.out.print(\"Linked List: \");\n        ListNode.printList(head);\n        \n        ListNode start = detectCycle(head);\n        if (start != null) {\n            System.out.println(\"Cycle detected! Starts at node with value: \" + start.val); // Expected: 2\n        } else {\n            System.out.println(\"No cycle detected.\");\n        }\n    }\n}\n"
