        "code": "\npublic class subarray_sum {\n    public static int sub(int arr[], int k) {\n        int n = arr.length;\n        int sum = 0, max = 0;\n        for (int i = 0; i < k; i++) {\n            sum += arr[i];\n        }\n        max = Math.max(sum / k, 0);\n        for (int i = k; i < n; i++) {\n            sum = sum - arr[i - k] + arr[i];\n            max = Math.max(sum / k, 0);\n        }\n        return max;\n    }\n\n    public static void main(String args[]) {\n        int arr[] = new int[] { 199, 89, -21, 79, 0, 10 };\n        int k = 4;\n        System.out.println(sub(arr, k));\n    }\n\n}\n"
