        "title": "Word Wrap",
        "sourceUrl": "https://www.geeksforgeeks.org/word-wrap-problem-dp-19/",
        "fileName": "wordWrap.java",
        "filePath": "dp/wordWrap.java",
        "timeComplexity": "O(N)",
        "spaceComplexity": "O(1)",
        "approach": "Recursion + Memoization computing minimum extra space squares",
        "code": "\nimport java.util.*;\n\nclass wordWrap {\n\n    public int solve(int arr[], int i, int k, int dp[]) {\n        // base case\n        if (arr.length == i)\n            return 0;\n        // to check if computed or not\n        if (dp[i] != -1)\n            return dp[i];\n        // initialize ans\n        int ans = Integer.MAX_VALUE;\n        // intiallize length\n        int len = 0;\n        for (int j = i; j < arr.length; j++) {\n            len += arr[j];\n            // beacuse extra space is needed\n            int total = len + (j - i);\n            // if toatl is grater than k then cost =0;\n            int cost;\n            if (total > k)\n                break;\n            // if length and k are qual then cost is also 0\n            else if (j == arr.length - 1)\n                cost = 0;\n            else {\n                // cal the extra space needed\n                int x = k - total;\n                cost = x * x;\n\n            }\n            // call the recursive call\n            ans = Math.min(ans, cost + solve(arr, j + 1, k, dp));\n        }\n\n        return dp[i] = ans;\n\n    }\n\n    public int wordWrap(int arr[], int k) {\n        int dp[] = new int[arr.length];\n        // fill the array with -1;\n        Arrays.fill(dp, -1);\n        return solve(arr, 0, k, dp);\n    }\n\n    public static void main(String[] args) {\n        int arr[] = { 1, 2, 3, 4, 5 };\n        int k = 10;\n        wordWrap ob = new wordWrap();\n        System.out.println(ob.wordWrap(arr, k));\n    }\n}"
