        "fileName": "Search2DMatrix.java",
        "filePath": "Arrays/searching/BinarySearch/Search2DMatrix.java",
        "timeComplexity": "O(\\log(M \\cdot N))",
        "spaceComplexity": "O(1)",
        "approach": "Flat virtual index mapping to row/col indices",
        "code": "// LeetCode 74: Search a 2D Matrix\n// Time Complexity: O(log(M * N)) where M is the number of rows and N is the number of columns\n// Space Complexity: O(1) auxiliary space\n\npublic class Search2DMatrix {\n\n    /**\n     * Searches for a target value in an M x N matrix.\n     * @param matrix The sorted 2D matrix\n     * @param target The target value\n     * @return True if target exists, otherwise false\n     */\n    public static boolean searchMatrix(int[][] matrix, int target) {\n        if (matrix == null || matrix.length == 0 || matrix[0].length == 0) {\n            return false;\n        }\n\n        int m = matrix.length;\n        int n = matrix[0].length;\n        int low = 0;\n        int high = m * n - 1;\n\n        while (low <= high) {\n            int mid = low + (high - low) / 2;\n            \n            // Map virtual 1D index to 2D coordinates\n            int row = mid / n;\n            int col = mid % n;\n            int val = matrix[row][col];\n\n            if (val == target) {\n                return true;\n            } else if (val < target) {\n                low = mid + 1;\n            } else {\n                high = mid - 1;\n            }\n        }\n\n        return false;\n    }\n\n    public static void main(String[] args) {\n        int[][] matrix = {\n            {1, 3, 5, 7},\n            {10, 11, 16, 20},\n            {23, 30, 34, 60}\n        };\n\n        System.out.println(\"Input Matrix:\");\n        for (int[] row : matrix) {\n            System.out.print(\"  [ \");\n            for (int val : row) {\n                System.out.print(val + \" \");\n            }\n            System.out.println(\"]\");\n        }\n        System.out.println();\n\n        System.out.println(\"Target: 3\");\n        System.out.println(\"Expected: true, Actual: \" + searchMatrix(matrix, 3));\n        System.out.println();\n\n        System.out.println(\"Target: 13\");\n        System.out.println(\"Expected: false, Actual: \" + searchMatrix(matrix, 13));\n        System.out.println();\n\n        System.out.println(\"Target: 60\");\n        System.out.println(\"Expected: true, Actual: \" + searchMatrix(matrix, 60));\n    }\n}\n"
